class LegacyRuntimeCollector{static const protocolPrefix='ADDKO_RPC ';final List<LegacyPluginItem> _items=[];final List<String> _logs=[],_builtins=[];String? _contentType,_category,_errorMessage;LegacyPluginItem? _resolvedItem;bool _succeeded=true;void consumeStdoutLine(String line){if(!line.startsWith(protocolPrefix)){if(line.trim().isNotEmpty)_logs.add(line);return;}final Object? decoded;try{decoded=jsonDecode(line.substring(protocolPrefix.length));}on FormatException{_logs.add('Protocol parse error');return;}if(decoded is! Map)return;final event=Map<String,Object?>.from(decoded),raw=event['params'];final m=raw is Map?Map<String,Object?>.from(raw):const <String,Object?>{};switch(event['method']?.toString()){case'xbmcplugin.addDirectoryItem':final x=m['item'];if(x is Map){final j=Map<String,Object?>.from(x)..['url']=m['url']?.toString()??''..['is_folder']=m['is_folder']==true;_items.add(LegacyPluginItem.fromJson(j));}break;case'xbmcplugin.addDirectoryItems':final xs=m['items'];if(xs is List){for(final x in xs){if(x is! Map)continue;final e=Map<String,Object?>.from(x),ri=e['item'];if(ri is Map){final j=Map<String,Object?>.from(ri)..['url']=e['url']?.toString()??''..['is_folder']=e['is_folder']==true;_items.add(LegacyPluginItem.fromJson(j));}}}break;case'xbmcplugin.setContent':_contentType=m['content']?.toString();break;case'xbmcplugin.setPluginCategory':_category=m['category']?.toString();break;case'xbmcplugin.setResolvedUrl':_succeeded=m['succeeded']!=false;final x=m['item'];if(x is Map)_resolvedItem=LegacyPluginItem.fromJson(Map<String,Object?>.from(x));break;case'xbmc.executebuiltin':final f=m['function']?.toString().trim();if(f?.isNotEmpty==true)_builtins.add(f!);break;case'xbmcaddon.openSettings':final id=m['addon_id']?.toString().trim();if(id?.isNotEmpty==true)_builtins.add('Addon.OpenSettings($id)');break;case'xbmc.log':final msg=m['message']?.toString();if(msg?.isNotEmpty==true)_logs.add(msg!);break;case'invocation.error':_succeeded=false;_errorMessage=m['me